INSERT INTO `activities` VALUES (24,'Laqua Vineyard – Menu degustazione Prologo per Una persona',NULL,NULL,6,'Questo buono regalo è valido per Menù Degustazione Prologo destinato a una persona al ristorante una stella Michelin dello Chef Antonino Cannavacciuolo',NULL,NULL,'Menù Degustazione Prologo (bevande non incluse)',NULL,NULL,'Si accettano esclusivamente prenotazioni per il servizio della cena dal mercoledì al giovedì e del pranzo di venerdì, esclusi i giorni festivi.',NULL,NULL,110,NULL,NULL,'2024-03-30 10:24:23','2026-02-12 12:27:38','Per prenotazioni scrivere una mail a vineyard@laquacollection.it oppure telefonare al 00390587346782, indicando il possesso del buono. Eventuali extra non inclusi nella dicitura sono da saldare in loco.\r\n\r\nLAQUA VINEYARD - Via del Teatro, 8, 56030 Casanova (Pisa - Toscana)',NULL,NULL,'ipratico','00071_-1'),(25,'Laqua Vineyard – Menu degustazione Prologo con bevande per Una persona',NULL,NULL,6,'Questo buono regalo è valido per Menù Degustazione Prologo destinato a una persona al ristorante una stella Michelin dello Chef Antonino Cannavacciuolo',NULL,NULL,'Menù Degustazione Prologo accompagnato da calice di aperitivo, degustazione vini, minerali e caffetteria.',NULL,NULL,'Si accettano esclusivamente prenotazioni per il servizio della cena dal mercoledì al giovedì e del pranzo di venerdì, esclusi i giorni festivi.',NULL,NULL,210,NULL,NULL,'2024-03-30 10:26:03','2026-02-12 12:27:28','Per prenotazioni scrivere una mail a vineyard@laquacollection.it oppure telefonare al 00390587346782, indicando il possesso del buono. Eventuali extra non inclusi nella dicitura sono da saldare in loco.\r\n\r\nLAQUA VINEYARD - Via del Teatro, 8, 56030 Casanova (Pisa - Toscana)',NULL,NULL,'ipratico','00072_-1'),(26,'Laqua Vineyard – Menu degustazione Interludio per Una persona',NULL,NULL,6,'Questo buono regalo è valido per Menù Degustazione Interludio destinato a una persona al ristorante una stella Michelin dello Chef Antonino Cannavacciuolo',NULL,