/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bookings` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `location_id` bigint unsigned DEFAULT NULL,
  `prenota_location_id` bigint unsigned DEFAULT NULL,
  `restaurant_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `date_from` date NOT NULL,
  `date_to` date NOT NULL,
  `api_version` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '2',
  `request_url` varchar(1024) COLLATE utf8mb4_unicode_ci NOT NULL,
  `http_status` int unsigned DEFAULT NULL,
  `success` tinyint(1) NOT NULL DEFAULT '0',
  `error_message` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `response_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `num_reservations` int unsigned NOT NULL DEFAULT '0',
  `executed_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `bookings_location_id_executed_at_index` (`location_id`,`executed_at`),
  KEY `bookings_restaurant_id_index` (`restaurant_id`),
  KEY `bookings_date_from_index` (`date_from`),
  KEY `bookings_date_to_index` (`date_to`),
  KEY `bookings_prenota_location_id_foreign` (`prenota_location_id`),
  CONSTRAINT `bookings_location_id_foreign` FOREIGN KEY (`location_id`) REFERENCES `locations` (`id`) ON DELETE SET NULL,
  CONSTRAINT `bookings_prenota_location_id_foreign` FOREIGN KEY (`prenota_location_id`) REFERENCES `prenota_locations` (`id`) ON DELETE SET NULL,
  CONSTRAINT `bookings_chk_1` CHECK (json_valid(`response_json`))
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
